23	// 例外中介層：任何未處理例外寫一行 log（型別、訊息、request_id）並回 500；OOM 這類也會留在 logs.jsonl 與 stderr。
24	app.Use(async (ctx, next) =>
25	{
26	    try { await next(); }
27	    catch (Exception ex)
28	    {
29	        var rid = ctx.Request.Headers["X-Request-Id"].FirstOrDefault();
30	        try { log.Write(new { level = "ERROR", @event = "unhandled_exception", request_id = rid, path = ctx.Request.Path.Value, exception = ex.GetType().FullName, message = ex.Message }); } catch { }
