39	app.MapPost("/orders", async (HttpRequest req) =>
40	{   // 建單（測試用）：body {id, shipped, paid}
41	    using var doc = await JsonDocument.ParseAsync(req.Body); var r = doc.RootElement;
42	    var id = r.GetProperty("id").GetString()!;
43	    var order = new Order(r.TryGetProperty("shipped", out var s) && s.GetBoolean(), r.TryGetProperty("paid", out var p) && p.GetBoolean(), false);
44	    store.Put(id, order);
45	    return Results.Ok(new { id, order });
46	});
47	app.MapGet("/orders/{id}", (string id) => store.TryGet(id, out var o) ? Results.Ok(new { id, order = o }) : Results.NotFound());
48	app.MapPost("/orders/{id}/cancel", async (string id, HttpRequest req) =>
49	{
50	    var t0 = DateTime.UtcNow;
51	    string? payload = null;
52	    if (req.ContentLength > 0) { using var sr = new StreamReader(req.Body); payload = await sr.ReadToEndAsync(); }
53	    if (faults.RetainPayloads) Retained.Keep(id, payload);   // 演練注入：把每筆 request body 留在記憶體，無上限
54	    var rid = req.Headers["X-Request-Id"].FirstOrDefault() ?? Guid.NewGuid().ToString("N")[..12];
55	    var runId = req.Headers["X-Run-Id"].FirstOrDefault();
56	    var actor = req.Headers["X-Actor"].FirstOrDefault();
57	    if (string.IsNullOrEmpty(actor))
58	    {
59	        metrics.Inc("cancel_requests_total", "unauthorized");
60	        log.Write(new { level = "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, result = "unauthorized" });
61	        return Results.Json(new { ok = false, reason = "unauthorized", request_id = rid }, statusCode: 401);
62	    }
63	    if (!store.TryCancel(id, out var before, out var result))
64	    {
65	        metrics.Inc("cancel_requests_total", "not_found");
66	        log.Write(new { level = "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, result = "not_found" });
67	        return Results.Json(new { ok = false, reason = "not_found", request_id = rid }, statusCode: 404);
68	    }
69	    // Teaching scheduler: disabled by default; widens the existing race window.
70	    if (int.TryParse(Environment.GetEnvironmentVariable("OC_TEST_DELAY_MS"), out var waitMs) && waitMs > 0) await Task.Delay(Math.Min(waitMs, 100));
71	    bool transitioned = Cancellation.Transitioned(before, result);
72	    string outcome; int status;
73	    if (before.Shipped) { outcome = "rejected_shipped"; status = 409; }          // BR-02，不通知（NC-03）
74	    else if (transitioned) { outcome = "ok"; status = 200; }
75	    else { outcome = "idempotent"; status = 200; }                               // BR-04／NC-02，不通知
76	    metrics.Inc("cancel_requests_total", outcome);
77	    string? notificationId = null;
78	    if (transitioned)
79	    {
80	        metrics.Inc("transitions_total");
81	        var n = new Notification(Guid.NewGuid().ToString("N"), id, rid, runId, "order_cancelled", result.RefundRequested);
82	        notificationId = n.NotificationId;
83	        metrics.Inc("notify_enqueued_total");
84	        if (faults.SyncNotify)
85	            await NotificationWorker.SendOnce(n, metrics, log, Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify");   // 演練注入：在請求路徑上同步等接收端
86	        else
87	            await channel.Writer.WriteAsync(n);
88	    }
89	    var lat = (DateTime.UtcNow - t0).TotalMilliseconds;
90	    metrics.ObserveLatency(lat);
91	    log.Write(new { level = status == 200 ? "INFO" : "WARN", @event = "cancel", request_id = rid, run_id = runId, order_id = id, actor, notification_id = notificationId, result = outcome, transitioned, refund_requested = result.RefundRequested, latency_ms = Math.Round(lat, 1), queue_depth = channel.Reader.Count });
92	    return Results.Json(new { ok = status == 200, transitioned, refund_requested = result.RefundRequested, reason = status == 200 ? null : outcome, request_id = rid, notification_id = notificationId, order = status == 200 ? result.Order : before }, statusCode: status);
93	});
94	app.MapGet("/metrics", () => Results.Text(metrics.Render(channel.Reader.Count, version), "text/plain"));
95	app.Run();
96	
97	record Notification(string NotificationId, string OrderId, string RequestId, string? RunId, string Kind, bool RefundRequested, int Deferrals = 0);
