99	sealed class OrderStore
100	{
101	    readonly Dictionary<string, Order> _d = new(); readonly object _g = new();
102	    public void Put(string id, Order o) { lock (_g) _d[id] = o; }
103	    public bool TryGet(string id, out Order o) { lock (_g) return _d.TryGetValue(id, out o!); }
104	    public bool TryCancel(string id, out Order before, out CancellationResult result)
105	    {
106	        lock (_g)
107	        {
108	            if (!_d.TryGetValue(id, out before!)) { result = null!; return false; }
109	            result = Cancellation.Cancel(before);
110	            _d[id] = result.Order;
111	            return true;
112	        }
113	    }
114	
115	}
