117	sealed class Metrics
118	{
119	    readonly Dictionary<string, long> _c = new(); readonly object _g = new();
120	    public void Inc(string name, string? label = null)
121	    {
122	        var k = label is null ? name : name + "{result=\"" + label + "\"}";
123	        lock (_g) _c[k] = _c.GetValueOrDefault(k) + 1;
124	    }
125	    static readonly double[] Buckets = { 5, 10, 25, 50, 100, 250, 500, 1000, 2500, 5000 };
126	    readonly long[] _hist = new long[Buckets.Length + 1]; double _latSum; long _latCount;
127	    public void ObserveLatency(double ms)
128	    {
129	        lock (_g) { _latSum += ms; _latCount++; int i = 0; while (i < Buckets.Length && ms > Buckets[i]) i++; _hist[i]++; }
130	    }
131	    public string Render(int depth, string version)
132	    {
133	        lock (_g)
134	        {
135	            var sb = new System.Text.StringBuilder();
136	            foreach (var kv in _c.OrderBy(k => k.Key)) sb.Append("oc_").Append(kv.Key).Append(' ').Append(kv.Value).Append('\n');
137	            sb.Append("oc_notify_queue_depth ").Append(depth).Append('\n');
138	            long cum = 0;
139	            for (int i = 0; i < Buckets.Length; i++) { cum += _hist[i]; sb.Append("oc_request_latency_ms_bucket{le=\"").Append(Buckets[i]).Append("\"} ").Append(cum).Append('\n'); }
140	            cum += _hist[Buckets.Length]; sb.Append("oc_request_latency_ms_bucket{le=\"+Inf\"} ").Append(cum).Append('\n');
141	            sb.Append("oc_request_latency_ms_sum ").Append(Math.Round(_latSum, 1)).Append('\n').Append("oc_request_latency_ms_count ").Append(_latCount).Append('\n');
142	            sb.Append("oc_gc_heap_bytes ").Append(GC.GetTotalMemory(false)).Append('\n');
143	            sb.Append("oc_working_set_bytes ").Append(Environment.WorkingSet).Append('\n');
144	            sb.Append("oc_gc_collections_gen2 ").Append(GC.CollectionCount(2)).Append('\n');
145	            sb.Append("oc_info{version=\"").Append(version).Append("\"} 1\n");
146	            return sb.ToString();
147	        }
148	    }
149	}
