151	sealed class JsonlLog
152	{
153	    readonly string _p; readonly string _v; readonly object _g = new();
154	    public JsonlLog(string p, string v) { _p = p; _v = v; }
155	    public void Write(object o)
156	    {
157	        var d = JsonSerializer.SerializeToNode(o)!.AsObject();
158	        d["ts"] = DateTimeOffset.Now.ToString("o"); d["version"] = _v;
159	        lock (_g) File.AppendAllText(_p, d.ToJsonString() + "\n");
160	    }
161	}
162	
163	// 演練注入 retain_payloads 的落點（v1.2.0 修復後）：客服查詢暫存改為有上限的環狀緩衝——最多 MaxItems 筆、每筆只留前 MaxBodyChars 字與原長度。
164	// v1.1.0 之前是無上限的 List，壓力下把 heap 撐到上限（見 evidence/runs/oom-retained-payloads-*、diagnosis/oom）。
165	static class Retained
166	{
167	    const int MaxItems = 256, MaxBodyChars = 256;
168	    static readonly Queue<(string OrderId, string Head, int Length)> _items = new(); static readonly object _g = new();
169	    public static void Keep(string orderId, string? body)
170	    {
171	        var b = body ?? "";
172	        lock (_g) { _items.Enqueue((orderId, b.Length > MaxBodyChars ? b[..MaxBodyChars] : b, b.Length)); while (_items.Count > MaxItems) _items.Dequeue(); }
173	    }
174	    public static int Count { get { lock (_g) return _items.Count; } }
175	}
176	
177	sealed class Faults
178	{
179	    public int? DropOverQueue; public int DelayMs; public bool RetainPayloads; public bool SyncNotify;
180	    public bool Any => DropOverQueue is not null || DelayMs > 0 || RetainPayloads || SyncNotify;
181	    public static Faults Load(string? path)
182	    {
183	        var f = new Faults();
184	        if (string.IsNullOrEmpty(path) || !File.Exists(path)) return f;
185	        using var doc = JsonDocument.Parse(File.ReadAllText(path)); var r = doc.RootElement;
186	        if (r.TryGetProperty("notify_drop_over_queue", out var q)) f.DropOverQueue = q.GetInt32();
187	        if (r.TryGetProperty("notify_delay_ms", out var d)) f.DelayMs = d.GetInt32();
188	        if (r.TryGetProperty("retain_payloads", out var rp)) f.RetainPayloads = rp.GetBoolean();
189	        if (r.TryGetProperty("sync_notify", out var sn)) f.SyncNotify = sn.GetBoolean();
190	        return f;
191	    }
192	}
193	
194	// 通知 worker：從 channel 取出 → POST sink → 失敗重試 3 次（200／400／800 ms）→ 超過進 dead_letter（NC-05）。
195	// 故障 notify_drop_over_queue（演練用）：佇列深度超過 N 時觸發「壓力延後」路徑。
196	// v1.0.0 的行為是記一行 notify_deferred 後不再重送、sent 計數照加（服務說送了、接收端沒收據）；v1.1.0 改為重排到隊尾、sent 只在 ack 後才加。
197	// 這條故障設計移植自 O 服務 fault-A；是演練用注入，不是自然事故。
198	sealed class NotificationWorker : BackgroundService
199	{
200	    readonly Channel<Notification> _ch; readonly Metrics _m; readonly JsonlLog _log; readonly Faults _f; readonly HttpClient _http = new();
201	    readonly string _sink = Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify";
202	    static readonly int[] Backoff = { 200, 400, 800 };
203	    const int MaxDeferrals = 5;
204	    public NotificationWorker(Channel<Notification> ch, Metrics m, JsonlLog log, Faults f) { _ch = ch; _m = m; _log = log; _f = f; }
205	    static readonly HttpClient SharedHttp = new();
206	    /// 同步送一次（含重試），供 sync_notify 演練路徑使用；計數規則與 worker 相同。
207	    public static async Task SendOnce(Notification n, Metrics m, JsonlLog log, string sink)
208	    {
209	        bool sent = false;
210	        for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
211	        {
212	            try
213	            {
214	                var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
215	                var resp = await SharedHttp.PostAsync(sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"));
216	                sent = resp.IsSuccessStatusCode;
217	            }
218	            catch (Exception e) { log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name }); }
219	            if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt]);
220	        }
221	        if (sent) { m.Inc("notify_sent_total"); log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, sync = true }); }
222	        else { m.Inc("notify_failed_total"); m.Inc("notify_dead_letter_total"); log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 }); }
223	    }
224	    protected override async Task ExecuteAsync(CancellationToken ct)
225	    {
226	        await foreach (var n in _ch.Reader.ReadAllAsync(ct))
227	        {
228	            if (_f.DelayMs > 0) await Task.Delay(_f.DelayMs, ct);
229	            if (_f.DropOverQueue is int q && _ch.Reader.Count > q)
230	            {   // v1.1.0 修復：壓力下不再「假裝送了」。延後＝重排到隊尾（最多 MaxDeferrals 次），sent_total 只在接收端 ack 後才加；延後另計。
231	                if (n.Deferrals < MaxDeferrals)
232	                {
233	                    _m.Inc("notify_deferred_total");
234	                    _log.Write(new { level = "INFO", @event = "notify_deferred", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, queue_depth = _ch.Reader.Count, deferrals = n.Deferrals + 1, requeued = true });
235	                    await _ch.Writer.WriteAsync(n with { Deferrals = n.Deferrals + 1 }, ct);
236	                    continue;
237	                }
238	                _log.Write(new { level = "WARN", @event = "notify_deferral_limit", notification_id = n.NotificationId, deferrals = n.Deferrals, note = "超過延後上限，改走一般送出／重試路徑" });
239	            }
240	            bool sent = false;
241	            for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
242	            {
243	                try
244	                {
245	                    var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
246	                    var resp = await _http.PostAsync(_sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"), ct);
247	                    sent = resp.IsSuccessStatusCode;
248	                    if (!sent) _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, status = (int)resp.StatusCode });
249	                }
250	                catch (Exception e) when (!ct.IsCancellationRequested)
251	                {
252	                    _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name });
253	                }
254	                if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt], ct);
255	            }
256	            if (sent)
257	            {
258	                _m.Inc("notify_sent_total");
259	                _log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId });
260	            }
261	            else
262	            {
263	                _m.Inc("notify_failed_total"); _m.Inc("notify_dead_letter_total");
264	                _log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 });
265	            }
266	        }
267	    }
268	}
